#!/usr/bin/env python3
# LinBASIC Studio - evaluation order tests: the programs of the experiments that measured in which order VB6
# evaluates the parts of expressions and statements (expN/; generated by expN/gen*.py), compiled with lbvc
# in each mode of VB6's Compile tab, and compared line by line with what the same program printed when
# VB6 SP6 compiled it that way (expected/orderN-MODE.txt). The model is compiler/lbvc/evalorder.py.
# Copyright (C) 2026 Demosthenes Koptsis. GPL-3.0-or-later.
#   python3 tests/order/run_tests.py [order4-Fast ...]
import glob, os, re, shutil, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', '..', 'compiler'))
from lbvc.driver import compile_project, build_exe, find_runtime, parse_order   # noqa: E402

EXPS = {1: ['OrderTest.bas'], 2: ['Order2.bas'], 3: ['Order3.bas', 'CLeaf.cls'], 4: ['Order4.bas', 'CLeaf.cls']}
# the name of the VB6 build -> lbvc --order
MODES = {'Pcode': 'pcode', 'Fast': 'fast', 'Small': 'small', 'NoOpt': 'noopt', 'FastAdv': 'fast,overflow,bounds',
         'FastOverflow': 'fast,overflow', 'FastBounds': 'fast,bounds'}


def lines(data):
    return data.decode('cp1252').replace('\r', '').rstrip('\n').split('\n')


def run(exp, mode, rt, work):
    d = os.path.join(work, f"order{exp}-{mode}")
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    files = []
    for f in EXPS[exp]:
        src = open(os.path.join(HERE, f"exp{exp}", f), 'rb').read()
        src = re.sub(rb'(?m)^\s*MsgBox "Done.*$', b'', src)        # (the end of the run in VB6)
        open(os.path.join(d, f), 'wb').write(src)
        files.append(os.path.join(d, f))
    csrc, _ = compile_project(files, order=parse_order(MODES[mode]))
    exe = build_exe(csrc, os.path.join(d, 'prog'), rt) or os.path.join(d, 'prog')
    env = dict(os.environ, VBRT_NO_ERRBOX='1')
    subprocess.run([exe], cwd=d, capture_output=True, timeout=300, env=env)
    out = glob.glob(os.path.join(d, '*.txt'))
    return lines(open(out[0], 'rb').read()) if out else []


def main():
    names = sorted(os.path.basename(p)[:-4] for p in glob.glob(os.path.join(HERE, 'expected', 'order*-*.txt')))
    if sys.argv[1:]:
        names = [n for n in names if n in sys.argv[1:]]
    rt = find_runtime()
    work = os.path.join(HERE, 'work')
    failed = 0
    for n in names:
        m = re.fullmatch(r'order(\d)-(\w+)', n)
        exp, mode = int(m.group(1)), m.group(2)
        want = lines(open(os.path.join(HERE, 'expected', n + '.txt'), 'rb').read())
        try:
            got = run(exp, mode, rt, work)
        except Exception as e:
            print(f"FAIL {n} (compile): {e}")
            failed += 1
            continue
        bad = [(w, g) for w, g in zip(want, got) if w != g]
        if len(got) != len(want):
            bad.append((f"{len(want)} lines", f"{len(got)} lines"))
        if bad:
            failed += 1
            print(f"FAIL {n}: {len(bad)} of {len(want)} lines differ")
            for w, g in bad[:6]:
                print(f"    VB6:    {w}\n    LinBASIC: {g}")
        else:
            print(f"ok   {n} ({len(want)} lines)")
    print(f"{len(names) - failed} passed, {failed} failed")
    return 1 if failed else 0


if __name__ == '__main__':
    sys.exit(main())
